export default function prepareCommunication({ text }) {
  if (typeof text !== "string" || !text.trim()) throw new Error("Communication text is required.");
  const schema = {
    type: "object",
    properties: {
      name: { type: "string", description: "Name of the user" },
      surname: { type: "string", description: "Surname of the user" },
      commtype: {
        type: "string",
        enum: ["email", "phone", "other"],
        description: "Method of communication",
      },
      contacts: { type: "string", description: "Contact details. ONLY IF PROVIDED" },
      timestamp: {
        type: "string",
        format: "date-time",
        description: "When the communication occurred",
      },
      subject: { type: "string", description: "Brief description of the communication topic" },
    },
    required: ["name", "commtype"],
  };
  const now = new Date().toISOString();
  return {
    text,
    now,
    instructions:
      'Please analyse the incoming communication. Extract information according to the JSON schema. Today is: "' +
      now +
      '". Include contacts only if provided in the text. Return only a JSON object; do not invent missing optional fields.\n\nJSON schema:\n' +
      JSON.stringify(schema),
  };
}

